class FoodChain {

    private static final String[] CREATURES = {
        "fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"
    };

    private static final String[] REACTIONS = {
        "",
        "It wriggled and jiggled and tickled inside her.",
        "How absurd to swallow a bird!",
        "Imagine that, to swallow a cat!",
        "What a hog, to swallow a dog!",
        "Just opened her throat and swallowed a goat!",
        "I don't know how she swallowed a cow!",
        "She's dead, of course!"
    };

    String verse(int verse) {
        int index = verse - 1;
        StringBuilder sb = new StringBuilder();
        String creature = CREATURES[index];

        sb.append("I know an old lady who swallowed a ").append(creature).append(".\n");

        if (index == CREATURES.length - 1) {
            sb.append(REACTIONS[index]);
            return sb.toString();
        }

        if (!REACTIONS[index].isEmpty()) {
            sb.append(REACTIONS[index]).append('\n');
        }

        for (int i = index; i > 0; i--) {
            sb.append("She swallowed the ").append(CREATURES[i])
              .append(" to catch the ").append(CREATURES[i - 1]);
            if (i - 1 == 1) {
                sb.append(" that wriggled and jiggled and tickled inside her");
            }
            sb.append(".\n");
        }

        sb.append("I don't know why she swallowed the fly. Perhaps she'll die.");
        return sb.toString();
    }

    String verses(int startVerse, int endVerse) {
        StringBuilder sb = new StringBuilder();
        for (int v = startVerse; v <= endVerse; v++) {
            if (v > startVerse) {
                sb.append('\n');
            }
            sb.append(verse(v));
        }
        return sb.toString();
    }

}

